<?php
/*
 * Pilihan metode pembayaran dengan logo.
 * Dipakai oleh cart.php dan beli_langsung.php.
 *
 * Nilai yang dikirim ke Checkout.php TIDAK berubah:
 * name="metode_pembayaran", value = "<Grup> - <Nama>"
 * (contoh: "Virtual Account - BCA", "E-Wallet - GoPay").
 *
 * Logo bawaan disematkan (data URI) di fungsi logoPembayaran() di bawah.
 * Untuk mengganti logo, cukup taruh file gambar di assets/images/pembayaran/
 * (lihat penjelasan di atas fungsi logoPembayaran).
 */

function daftarMetodePembayaran()
{
    return [
        'Virtual Account' => [
            ['Mandiri', 'mandiri'],
            ['BCA',     'bca'],
            ['BNI',     'bni'],
            ['BRI',     'bri'],
        ],
        'E-Wallet' => [
            ['GoPay',     'gopay'],
            ['OVO',       'ovo'],
            ['ShopeePay', 'shopeepay'],
        ],
    ];
}

function tampilMetodePembayaran()
{
    ?>

    <fieldset class="pay-picker">

        <legend>Metode Pembayaran</legend>

        <?php foreach (daftarMetodePembayaran() as $grup => $daftar): ?>

            <p class="pay-group"><?= htmlspecialchars($grup) ?></p>

            <div class="pay-options">

                <?php foreach ($daftar as $m): ?>

                    <label class="pay-option">

                        <input
                            type="radio"
                            name="metode_pembayaran"
                            value="<?= htmlspecialchars($grup . ' - ' . $m[0]) ?>"
                            required
                        >

                        <span class="pay-card">

                            <span class="pay-logo">
                                <?php $logo = logoPembayaran($m[1]); ?>
                                <?php if ($logo !== ''): ?>
                                    <img src="<?= $logo ?>" alt="" loading="lazy">
                                <?php endif; ?>
                            </span>

                            <span class="pay-name"><?= htmlspecialchars($m[0]) ?></span>

                            <span class="pay-check" aria-hidden="true">✓</span>

                        </span>

                    </label>

                <?php endforeach; ?>

            </div>

        <?php endforeach; ?>

    </fieldset>

    <?php
}


/*
 * Logo metode pembayaran.
 *
 * GANTI LOGO SECARA MANUAL:
 *   Taruh file gambar di folder  assets/images/pembayaran/
 *   dengan nama sesuai kode:  mandiri, bca, bni, bri, gopay, ovo, shopeepay
 *   (format: .png / .svg / .webp / .jpg).  Contoh: assets/images/pembayaran/bca.png
 *   Kalau file ada, itu yang dipakai. Kalau tidak ada, dipakai logo bawaan
 *   (data URI) di bawah.
 */
function logoPembayaran($kode)
{
    foreach (['png', 'svg', 'webp', 'jpg', 'jpeg'] as $ext) {
        $rel  = 'assets/images/pembayaran/' . $kode . '.' . $ext;
        $full = __DIR__ . '/' . $rel;

        if (is_file($full)) {
            // ?v=... supaya browser langsung memuat logo terbaru
            return $rel . '?v=' . filemtime($full);
        }
    }

    /* Logo bawaan (PNG transparan, disematkan sebagai data URI) */
    static $logo = [
        'mandiri' => 'data:image/png;base64,',
        'bca' => 'data:image/png;base64,',
        'bni' => 'data:image/png;base64,',
        'bri' => 'data:image/png;base64,',
        'gopay' => 'data:image/png;base64,',
        'ovo' => 'data:image/png;base64,',
        'shopeepay' => 'data:image/png;base64,',
    ];

    return $logo[$kode] ?? '';
}